const pageProjectTranslations = `-- name: PageProjectTranslations :many
SELECT t.id, t.tenant_id, t.project_id, t.message_id, t.locale, t.syntax, t.text, t.model, t.state, t.origin, t.author, t.source_revision, t.warnings, t.revision, t.created_at, t.updated_at, m.key, m.namespace, m.state AS message_state, m.source_revision AS current_source_revision
FROM localization_messages m
JOIN localization_translations t ON t.message_id = m.message_id
JOIN localization_locales l ON l.project_id = t.project_id AND l.code = t.locale
WHERE m.project_id = $1
  AND t.project_id = $1
  AND t.locale = ANY ($2::text[])
  -- The first comparison is implied by the second; it is the one the
  -- index can seek to, so a deep page doesn't rescan earlier keys.
  AND (m.key, m.message_id) >= ($3::text, $4::uuid)
  AND (m.key, m.message_id, t.locale) > ($3::text, $4::uuid,
                                         $5::text)
  AND ($6::text[] IS NULL OR t.state = ANY ($6::text[]))
  -- Provenance, exactly as the column records it. ` + "`" + `agent` + "`" + ` and ` + "`" + `ai` + "`" + ` are
  -- different origins since migration 0032 and this is what makes the
  -- difference readable through the API rather than only in SQL.
  AND ($7::text[] IS NULL OR t.origin = ANY ($7::text[]))
  AND ($8::boolean IS NULL OR (t.source_revision < m.source_revision) = $8)
  AND ($9::text IS NULL OR m.namespace = $9)
  AND ($10::text IS NULL OR m.state = $10)
  AND ($11::text IS NULL OR m.key LIKE $11)
  -- Exactly these keys, for the messages on one screen: a key_prefix
  -- equal to a key would also match everything below it.
  AND ($12::text[] IS NULL OR m.key = ANY ($12::text[]))
  -- Only these units, each spelled "<message id> <locale>": an
  -- assigned member's (RFC 0006 §3.3), filtered before the LIMIT so a
  -- page's size and cursor say nothing about the units outside them.
  AND ($13::text[] IS NULL OR (t.message_id::text || ' ' || t.locale) = ANY ($13::text[]))
ORDER BY m.key, m.message_id, t.locale
LIMIT $14
`

